settings.custom_css:
.m-store-info {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  column-gap: 70px;
  row-gap: 70px;
  margin-top: 50px;
}

.m-store-info__item a {
  text-decoration: underline;
}

.m-store-info__item h4 {
  line-height: 26px;
  margin-bottom: 10px;
}

.m-store-info__item ul {
  display: flex;
  align-items: center;
  margin: 0 -15px;
  margin-top: 20px;
}

.m-store-info__item ul li {
  padding: 0 15px;
}

@media (max-width: 767px) {
  .m-store-info {
    grid-template-columns: auto;
    row-gap: 20px;
    margin-top: 10px;
  }
}
@media (min-width: 768px) {
  .m-store-info {
    column-gap: 50px;
    row-gap: 40px;
    margin-top: 30px;
  }
}
@media (min-width: 1024px) {
  .m-store-info {
    column-gap: 30px;
    row-gap: 30px;
    margin-top: 30px;
  }
}
